struct RingBuffer {
private:
    int cap;
    int head;
    int tail;
    int count;
    int data[1024];

public:
    RingBuffer(int capacity)
        : cap(capacity > 1024 ? 1024 : (capacity < 1 ? 1 : capacity)),
          head(0),
          tail(0),
          count(0) {}

    bool push(int value) {
        if (count == cap) return false;
        data[tail] = value;
        tail = (tail + 1) % cap;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (count == 0) return false;
        out = data[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int size() const {
        return count;
    }

    bool empty() const {
        return count == 0;
    }

    bool full() const {
        return count == cap;
    }
};

